// DataColumnSidecars computes the data column sidecars from the signed block, cells and cell proofs.
// The returned value contains pointers to function parameters.
// (If the caller alterates `cellsAndProofs` afterwards, the returned value will be modified as well.)
// https://github.com/ethereum/consensus-specs/blob/master/specs/fulu/validator.md#get_data_column_sidecars_from_block
func DataColumnSidecars(signedBlock interfaces.ReadOnlySignedBeaconBlock, cellsAndProofs []kzg.CellsAndProofs) ([]*ethpb.DataColumnSidecar, error) {
	if signedBlock == nil || signedBlock.IsNil() || len(cellsAndProofs) == 0 {
		return nil, nil
	}

	block := signedBlock.Block()
	blockBody := block.Body()
	blobKzgCommitments, err := blockBody.BlobKzgCommitments()
	if err != nil {
		return nil, errors.Wrap(err, "blob KZG commitments")
	}

	if len(blobKzgCommitments) != len(cellsAndProofs) {
		return nil, ErrSizeMismatch
	}

	signedBlockHeader, err := signedBlock.Header()
	if err != nil {
		return nil, errors.Wrap(err, "signed block header")
	}

	kzgCommitmentsInclusionProof, err := blocks.MerkleProofKZGCommitments(blockBody)
	if err != nil {
		return nil, errors.Wrap(err, "merkle proof KZG commitments")
	}

	dataColumnSidecars, err := dataColumnsSidecars(signedBlockHeader, blobKzgCommitments, kzgCommitmentsInclusionProof, cellsAndProofs)
	if err != nil {
		return nil, errors.Wrap(err, "data column sidecars")
	}

	return dataColumnSidecars, nil
}

// ComputeCustodyGroupForColumn computes the custody group for a given column.
// It is the reciprocal function of ComputeColumnsForCustodyGroup.
func ComputeCustodyGroupForColumn(columnIndex uint64) (uint64, error) {
	beaconConfig := params.BeaconConfig()
	numberOfColumns := beaconConfig.NumberOfColumns
	numberOfCustodyGroups := beaconConfig.NumberOfCustodyGroups

	if columnIndex >= numberOfColumns {
		return 0, ErrIndexTooLarge
	}

	return columnIndex % numberOfCustodyGroups, nil
}

// CustodyColumns computes the custody columns from the custody groups.
func CustodyColumns(custodyGroups []uint64) (map[uint64]bool, error) {
	numberOfCustodyGroups := params.BeaconConfig().NumberOfCustodyGroups

	custodyGroupCount := len(custodyGroups)

	// Compute the columns for each custody group.
	columns := make(map[uint64]bool, custodyGroupCount)
	for _, group := range custodyGroups {
		if group >= numberOfCustodyGroups {
			return nil, ErrCustodyGroupTooLarge
		}

		groupColumns, err := ComputeColumnsForCustodyGroup(group)
		if err != nil {
			return nil, errors.Wrap(err, "compute columns for custody group")
		}

		for _, column := range groupColumns {
			columns[column] = true
		}
	}

	return columns, nil
}

// dataColumnsSidecars computes the data column sidecars from the signed block header, the blob KZG commiments,
// the KZG commitment includion proofs and cells and cell proofs.

func setExecutionData(ctx context.Context, blk interfaces.SignedBeaconBlock, local *blocks.GetPayloadResponse, bid builder.Bid, builderBoostFactor primitives.Gwei) (primitives.Wei, enginev1.BlobsBundler, error) {
	_, span := trace.StartSpan(ctx, "ProposerServer.setExecutionData")
	defer span.End()

	slot := blk.Block().Slot()
	if slots.ToEpoch(slot) < params.BeaconConfig().BellatrixForkEpoch {
		return primitives.ZeroWei(), nil, nil
	}

	if local == nil {
		return primitives.ZeroWei(), nil, errors.New("local payload is nil")
	}

	// Use local payload if builder payload is nil.
	if bid == nil {
		return local.Bid, local.BlobsBundler, setLocalExecution(blk, local)
	}

	builderPayload, err := bid.Header()
	if err != nil {
		log.WithError(err).Warn("Proposer: failed to retrieve header from BuilderBid")
		return local.Bid, local.BlobsBundler, setLocalExecution(blk, local)
	}

	switch {
	case blk.Version() >= version.Capella:
		withdrawalsMatched, err := matchingWithdrawalsRoot(local.ExecutionData, builderPayload)
		if err != nil {
			tracing.AnnotateError(span, err)
			log.WithError(err).Warn("Proposer: failed to match withdrawals root")
			return local.Bid, local.BlobsBundler, setLocalExecution(blk, local)
		}

		// Compare payload values between local and builder. Default to the local value if it is higher.
		localValueGwei := primitives.WeiToGwei(local.Bid)
		builderValueGwei := primitives.WeiToGwei(bid.Value())
		minBid := primitives.Gwei(params.BeaconConfig().MinBuilderBid)
		// Use local block if min bid is not attained
		if builderValueGwei < minBid {
			log.WithFields(logrus.Fields{
				"minBuilderBid":    minBid,
				"builderGweiValue": builderValueGwei,
			}).Warn("Proposer: using local execution payload because min bid not attained")
			return local.Bid, local.BlobsBundler, setLocalExecution(blk, local)
		}

		// Use local block if min difference is not attained
		minDiff := localValueGwei + primitives.Gwei(params.BeaconConfig().MinBuilderDiff)
		if builderValueGwei < minDiff {
			log.WithFields(logrus.Fields{
				"localGweiValue":   localValueGwei,
				"minBidDiff":       minDiff,
				"builderGweiValue": builderValueGwei,
			}).Warn("Proposer: using local execution payload because min difference with local value was not attained")
			return local.Bid, local.BlobsBundler, setLocalExecution(blk, local)
		}

		// Use builder payload if the following in true:
		// builder_bid_value * builderBoostFactor(default 100) > local_block_value * (local-block-value-boost + 100)
		boost := primitives.Gwei(params.BeaconConfig().LocalBlockValueBoost)
		higherValueBuilder := builderValueGwei*builderBoostFactor > localValueGwei*(100+boost)
		if boost > 0 && builderBoostFactor != defaultBuilderBoostFactor {
			log.WithFields(logrus.Fields{
				"localGweiValue":       localValueGwei,
				"localBoostPercentage": boost,
				"builderGweiValue":     builderValueGwei,
				"builderBoostFactor":   builderBoostFactor,
			}).Warn("Proposer: both local boost and builder boost are using non default values")
		}
		builderValueGweiGauge.Set(float64(builderValueGwei))
		localValueGweiGauge.Set(float64(localValueGwei))

		// If we can't get the builder value, just use local block.
		if higherValueBuilder && withdrawalsMatched { // Builder value is higher and withdrawals match.
			var builderKzgCommitments [][]byte
			if bid.Version() >= version.Deneb {
				bidDeneb, ok := bid.(builder.BidDeneb)
